import {clonePlan,validatePlan,editSlot,assessPlan,searchLevels,TANK_LAYOUT} from './placement-model.mjs?v=2';
export function initPlacementLab({getSnapshot,pause,applyMain}){
 const host=document.querySelector('#placement-lab');if(!host)return;
 const $=s=>host.querySelector(s),fmt=(v,d=2)=>Number.isFinite(v)?v.toFixed(d):'계산 불가';
 let draft=null,baseline=null,search=null,first=true,capturedFingerprint='';
 host.innerHTML=`<div class="panel-header"><h2>적재·탱크 배치 실험</h2><span>배치 평가 · 3D 연동</span></div><div class="panel-pad">
 <p class="lab-warning">실제 안전 판정이 아닙니다. 가상 선박의 기울기·추정 GM·탱크 운전 범위를 비교합니다. 선체 강도·흘수·GZ·침수·실제 선박 복원성 자료는 검증하지 않습니다.</p>
 <p>실험안 B를 메인 3D에 적용하면 현재 하역 기록을 초기화하고 이 배치에서 새로 시작합니다. 적용 전에는 메인 상태를 유지합니다.</p>
 <div class="lab-actions"><button id="lab-capture" class="outline-btn">현재 시뮬레이션 상태 불러오기</button><button id="lab-empty" class="outline-btn">실험 화물 모두 비우기</button></div><p id="lab-context"></p><p id="lab-message" role="status"></p>
 <h3>1. 화물을 어느 칸에 얼마나 실을까요?</h3>
 <div class="lab-position"><label>높이<select id="lab-tier"><option value="0">하부 1층</option><option value="1">중간 2층</option><option value="2">상부 3층</option></select></label><label>길이 위치<select id="lab-bay">${Array.from({length:6},(_,i)=>`<option value="${i}">BAY ${i+1}${i===0?' · 선미측':i===5?' · 선수측':''}</option>`).join('')}</select></label><label>좌우 위치<select id="lab-row"><option value="0">ROW 1 · 좌현 바깥</option><option value="1">ROW 2 · 좌현 안쪽</option><option value="2">ROW 3 · 우현 안쪽</option><option value="3">ROW 4 · 우현 바깥</option></select></label></div>
 <p class="lab-map-hint">선미 ← BAY 1 … BAY 6 → 선수 · 위쪽 두 줄은 좌현, 아래 두 줄은 우현</p><div id="lab-grid" class="lab-grid" role="group" aria-label="실험 화물 배치도"></div>
 <div class="lab-position"><label>선택 칸 중량 (t)<input id="lab-weight" type="number" min="1" max="100" step=".1" value="20"></label><span id="lab-slot-status"></span></div><div class="lab-actions"><button id="lab-load" class="primary-btn">적재·중량 반영</button><button id="lab-unload" class="outline-btn">선택 화물 하역</button></div><p class="lab-small">중량은 칸당 가정 범위 1–100t입니다. 상부는 하부 적재 후 싣고, 하역은 위쪽부터 합니다. 입력만 한 중량은 반영 버튼 전까지 평가에 포함되지 않습니다.</p>
 <h3>2. 네 물탱크의 수량을 바꿔보세요.</h3><div class="lab-tanks">${TANK_LAYOUT.map((t,i)=>`<label>${t.name} (t)<input id="lab-tank-${i}" type="number" min="0" max="1200" step=".1" value="600"><meter id="lab-meter-${i}" min="0" max="1200" value="600"></meter><small id="lab-percent-${i}">반영 수량 50%</small></label>`).join('')}</div>
 <div class="lab-position"><label>합성 기울기 한도 (시연 °)<input id="lab-threshold" type="number" min=".1" max="10" step=".1" value="1.5"></label><button id="lab-evaluate" class="primary-btn">탱크 수량 반영·평가</button></div><p class="lab-small">용량은 탱크당 가정값 1200t입니다. 기존 모델 운전 범위는 80–1120t이며 법정 안전 기준이 아닙니다. 직접 수량 변경은 외부 주입·배출을 가정하므로 총량도 달라질 수 있습니다.</p>
 <h3>3. 반영된 배치를 비교해요.</h3><div class="lab-actions"><button id="lab-baseline" class="outline-btn">현재 배치를 기준안 A로 저장</button><button id="lab-export" class="outline-btn">입력·결과 JSON 저장</button></div><p class="lab-small">화물·탱크 수량을 고정하고 60초 동안 0.25초 간격으로 합성 외란을 계산합니다. 판정 항목은 기울기·GM·탱크 운전 범위입니다. 앞뒤 무게중심 편차는 참고 지표이며 실제 트림·강도 기준을 판정하지 않습니다. A/B는 같은 시연 한도를 사용합니다.</p><div id="lab-results" class="lab-results"></div>
 <h3>4. 같은 총 평형수로 다른 배치를 찾아요.</h3><button id="lab-search" class="primary-btn">탱크 배치 후보 찾기</button><p class="lab-small">현재 총량을 보존하며 40t 격자·현재점·좌우 모멘트 보정 후보를 검사합니다. 60초 합성 기울기 최대값, 하역 기울기, 앞뒤 무게중심 편차 순으로 비교합니다. 전역 최적해나 실제 안전 수량을 보장하지 않습니다. 펌프 이송시간·이송 중 과도상태는 이 배치 평가에 포함하지 않습니다.</p><div id="lab-candidates"></div><h3>5. 이 배치에서 하역을 재생해요.</h3><button id="lab-apply-main" class="primary-btn">실험안 B를 메인 3D에 적용</button><p class="lab-small">반영한 화물 위치·중량, 입력 탱크 수량, 저장된 환경·파도 위상·고정 KM을 복사합니다. 미반영 화물 중량은 먼저 적재·중량 반영을 누르세요. 새 실행은 일시정지로 준비되며, 시작 버튼을 눌러 남은 화물의 하역과 물 이송을 관찰합니다. 초기화는 이 배치를 복원하고 합성 예제 복원은 72칸 예제로 돌아갑니다.</p></div>`;
 function message(text,error=false){$('#lab-message').textContent=text;$('#lab-message').classList.toggle('error',error);}
 function selected(){return draft.slots.find(c=>c.bay===Number($('#lab-bay').value)&&c.row===Number($('#lab-row').value)&&c.tier===Number($('#lab-tier').value));}
 function waterInput(){const levels=TANK_LAYOUT.map((_,i)=>{const raw=$('#lab-tank-'+i).value;if(!raw.trim())throw Error('탱크 수량을 모두 입력하세요.');return Number(raw);});const raw=$('#lab-threshold').value;if(!raw.trim())throw Error('시연 기울기 한도를 입력하세요.');const next=validatePlan({...clonePlan(draft),levels,threshold:Number(raw)});if(baseline)baseline.threshold=next.threshold;return next;}
 function render({editor=false,water=false}={}){
  const c=selected();$('#lab-grid').replaceChildren(...draft.slots.filter(x=>x.tier===Number($('#lab-tier').value)).sort((a,b)=>a.row-b.row||a.bay-b.bay).map(x=>{const button=document.createElement('button');button.type='button';button.dataset.slot=x.id;button.className=(x.loaded?'loaded ':'')+(x.id===c.id?'selected':'');button.textContent=`B${x.bay+1}·R${x.row+1}\n${x.loaded?fmt(x.weight,1)+'t':'빈 칸'}`;button.setAttribute('aria-label',`${x.id} BAY ${x.bay+1} ROW ${x.row+1} ${x.loaded?x.weight+'t 적재':'빈 칸'}`);button.onclick=()=>{$('#lab-bay').value=String(x.bay);$('#lab-row').value=String(x.row);render({editor:true});};return button;}));
  if(editor)$('#lab-weight').value=String(c.weight);$('#lab-slot-status').textContent=`${c.id} · ${c.loaded?'반영된 중량 '+fmt(c.weight,1)+'t':'현재 빈 칸'}`;
  TANK_LAYOUT.forEach((_,i)=>{if(water)$('#lab-tank-'+i).value=String(draft.levels[i]);$('#lab-meter-'+i).value=draft.levels[i];$('#lab-percent-'+i).textContent=`반영 수량 ${fmt(draft.levels[i],1)}t · ${fmt(draft.levels[i]/12,1)}%`;});if(water)$('#lab-threshold').value=String(draft.threshold);
  $('#lab-context').textContent=`불러온 환경: ${draft.environment?.source??'기본 합성 파도 '+draft.wave} · 가상 ${fmt(draft.simulationTime??0,1)}초부터 60초 · 기준 KM ${fmt(draft.km)}m 고정. 새 환경·진행 상태를 쓰려면 현재 상태를 다시 불러오세요.`;
  const results=[['기준안 A',baseline],['실험안 B',draft]].map(([label,p])=>{const r=assessPlan(p);return `<section><h4>${label}</h4><strong class="${r.passes?'pass':'attention'}">${r.passes?'모델 항목만 충족 · 실제 안전 미판정':r.valid?'모델 기준 검토 필요':'모델 계산 범위 초과'}</strong><dl><dt>반영 화물</dt><dd>${r.loadedCount}칸 · ${fmt(r.cargoMass,1)}t</dd><dt>평형수 총량</dt><dd>${fmt(r.water,1)}t</dd><dt>탱크별 수량${label==='실험안 B'?' · A 대비 증감':''}</dt><dd class="lab-tank-summary">${TANK_LAYOUT.map((t,i)=>`<span>${t.name} ${fmt(p.levels[i],1)}t${label==='실험안 B'?' ('+(p.levels[i]-baseline.levels[i]>=0?'+':'')+fmt(p.levels[i]-baseline.levels[i],1)+'t)':''}</span>`).join('')}</dd><dt>계산 하역 기울기</dt><dd>${fmt(r.heel)}°</dd><dt>60초 합성 최대 |기울기|</dt><dd>${fmt(r.peak)}° / 한도 ${fmt(p.threshold)}°</dd><dt>추정 GM</dt><dd>${fmt(r.gm)}m / 기준 > 0.2m</dd><dt>탱크 운전 범위</dt><dd>${r.tankWithinRange?'4개 모두 범위 내':'80–1120t 범위 밖 있음'}</dd><dt>앞뒤 무게중심 편차</dt><dd>${fmt(r.lcg)}m (각도 아님)</dd></dl></section>`;});$('#lab-results').innerHTML=results.join('');
 }
 function invalidate(){search=null;$('#lab-candidates').replaceChildren();}
 function capture(){pause();const p=getSnapshot();capturedFingerprint=JSON.stringify(p);draft=validatePlan(clonePlan(p));baseline=clonePlan(draft);invalidate();first=false;render({editor:true,water:true});message('현재 상태를 기준안 A와 실험안 B로 불러왔습니다. 메인 시뮬레이션은 일시정지했습니다.');}
 function act(fn){try{fn();}catch(error){message(error.message,true);}}
 for(const id of ['lab-tier','lab-bay','lab-row'])$('#'+id).onchange=()=>{if(draft)render({editor:true});};
 $('#lab-capture').onclick=()=>act(capture);
 $('#lab-empty').onclick=()=>act(()=>{draft=validatePlan({...clonePlan(draft),slots:draft.slots.map(c=>({...c,loaded:false}))});invalidate();render({editor:true});message('실험안 B의 화물만 비웠습니다. 물탱크와 기준안 A는 유지됩니다.');});
 $('#lab-load').onclick=()=>act(()=>{const raw=$('#lab-weight').value;if(!raw.trim())throw Error('화물 중량을 입력하세요.');draft=editSlot(draft,selected().id,Number(raw),true);invalidate();render({editor:true});message('선택 칸의 적재·중량을 실험안 B에 반영했습니다.');});
 $('#lab-unload').onclick=()=>act(()=>{draft=editSlot(draft,selected().id,selected().weight,false);invalidate();render({editor:true});message('선택 칸을 실험안 B에서 하역했습니다.');});
 $('#lab-evaluate').onclick=()=>act(()=>{draft=waterInput();invalidate();render({water:true});message('탱크 수량과 시연 한도를 실험안 B에 반영했습니다.');});
 $('#lab-baseline').onclick=()=>act(()=>{draft=waterInput();baseline=clonePlan(draft);invalidate();render({water:true});message('현재 반영된 배치를 기준안 A로 저장했습니다.');});
 $('#lab-search').onclick=async()=>{const button=$('#lab-search');button.disabled=true;try{draft=waterInput();invalidate();render({water:true});message('같은 총량의 배치 후보를 검사 중입니다…');await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));search=searchLevels(draft);const status=document.createElement('p');status.textContent=`${search.checked.toLocaleString()}개 후보 검사 · 모델 기준 내 ${search.within.toLocaleString()}개 · 총량 ${fmt(search.total,1)}t 고정`;$('#lab-candidates').append(status);for(const [i,r]of search.candidates.entries()){const row=document.createElement('div');row.className='lab-candidate';const text=document.createElement('p');text.textContent=`후보 ${i+1}: ${TANK_LAYOUT.map((t,j)=>t.name+' '+fmt(r.levels[j],1)+'t ('+(r.levels[j]-draft.levels[j]>=0?'+':'')+fmt(r.levels[j]-draft.levels[j],1)+'t)').join(' / ')} · 합성 최대 ${fmt(r.peak)}° · GM ${fmt(r.gm)}m · 내부 이동 ${fmt(r.moved,1)}t · ${r.passes?'모델 기준 내':'모델 기준 초과'}`;const apply=document.createElement('button');apply.type='button';apply.className='outline-btn';apply.dataset.candidate=String(i);apply.textContent='후보 수량을 B에 반영';apply.onclick=()=>act(()=>{draft=validatePlan({...clonePlan(draft),levels:[...r.levels]});invalidate();render({water:true});message('후보 수량을 실험안 B에 반영했습니다. 실제 선박의 안전 수량 판정은 아닙니다.');});row.append(text,apply);$('#lab-candidates').append(row);}if(!search.candidates.length)message('현재 총량·운전 범위에서 유효한 후보가 없습니다. 총량 또는 적재 조건을 다시 설정하세요.',true);else if(!search.within)message('검사한 후보 중 모델 기준을 충족한 안이 없습니다. 표시 후보도 기준 초과이므로 적재·총량·환경을 다시 검토하세요.',true);else message('탐색 후보입니다. 기준 내 여부와 한계를 확인하고 실험안 B에 반영하세요.');}catch(error){message(error.message,true);}finally{button.disabled=false;}};
 $('#lab-apply-main').onclick=()=>act(()=>{const next=waterInput();applyMain(clonePlan(next));draft=next;capturedFingerprint=JSON.stringify(getSnapshot());invalidate();render({water:true});message('실험안 B를 메인 3D에 적용했습니다. 시작 버튼으로 하역을 재생하세요.');document.querySelector('#close-panel')?.click();});
 $('#lab-export').onclick=()=>act(()=>{const payload={type:'concept-model-placement-experiment',exportedAt:new Date().toISOString(),modelAssumptions:{baseMassTonnes:12000,baseKGMetres:6.5,fixedKMMetres:draft.km,tankCapacityTonnes:1200,operatingTankTonnes:[80,1120],minimumModelGMMetres:.2,cargoWeightTonnes:[1,100]},baseline,trial:draft,baselineResult:assessPlan(baseline),trialResult:assessPlan(draft),search,limitations:['Not an actual ship safety determination','Fixed assumed vessel KM and tank geometry','No draft, GZ, longitudinal strength or downflooding assessment','Static cargo/tank state; 60s sampled synthetic disturbance']};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='harbor-placement-experiment.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);message('반영된 기준안·실험안·환경·계산 결과를 JSON으로 저장했습니다.');});
 new MutationObserver(()=>{if(document.body.dataset.panel==='placement'){if(first)act(capture);else if(JSON.stringify(getSnapshot())!==capturedFingerprint)message('메인 환경 또는 진행 상태가 달라졌습니다. 이 실험안은 기존 스냅샷을 유지합니다. 현재 상태를 불러오면 A/B를 새로 시작합니다.',true);}}).observe(document.body,{attributes:true,attributeFilter:['data-panel']});
}
